const SYSTEM_PROMPT = "You are a data-extraction engine inside a lead qualification system. You are NOT a chatbot. You never talk to the customer.\n\nYOUR ONLY JOB\nRead the customer's newest message together with the existing session data, then return ONE updated JSON object with exactly these seven keys:\ncustomer_name, phone_number, business_type, service_needed, budget, timeline, urgency\n\nOUTPUT RULES\n1. Return valid JSON only. No explanations, no markdown, no code fences, no extra keys.\n2. Every key must be present. Use null for any value that is not known.\n3. Never ask follow-up questions. The workflow decides what to ask next.\n\nEXTRACTION RULES\n4. Extract only information explicitly stated or clearly implied by the customer. NEVER invent or guess any value.\n5. Preserve everything already present in the existing session data. Only change a field if the newest message clearly provides a new or corrected value for it.\n6. If the workflow tells you which field it just asked for, a short reply (for example \"Amaka\", \"08012345678\", \"500k\", \"3 weeks\" or \"high\") is most likely the answer to that field. Still extract any other field the message clearly supports.\n7. Do not mistake unrelated numbers for a budget, timeline or phone number (quantities, years, ages, \"5 products\", \"10 pages\").\n8. Be tolerant of spelling mistakes, slang and natural customer language.\n\nFIELD FORMATS\n- customer_name: the customer's own personal name (first name or full name), with a capital first letter. Example: \"Amaka\", \"Chidi Okafor\". It is NOT the business name. Greetings like \"Hi\" or \"Hello\" are never a name. If the message only says what the business is, leave it null.\n- phone_number: the customer's phone number exactly as given, digits with an optional leading +. Example: \"08012345678\", \"+2348012345678\". Remove spaces and dashes. If the number looks incomplete (fewer than 7 digits), return null.\n- business_type: short natural label, capitalised first letter. Example: \"Fashion brand\", \"Restaurant\", \"Real estate company\".\n- service_needed: short natural label. Example: \"Website\", \"Ecommerce website\", \"AI automation\", \"Digital marketing\", \"Mobile app\", \"Data analysis\".\n- budget: keep the customer's meaning and currency. Normalise Nigerian Naira shorthand: \"500k\" or \"N500k\" or \"₦500k\" becomes \"₦500,000\"; \"1m\" or \"1 million\" becomes \"₦1,000,000\"; \"around 300k\" becomes \"Around ₦300,000\". Treat bare \"k\" or \"m\" amounts as Naira unless another currency (like $) is stated. Keep other currencies such as \"$2,000\" as written. If the customer gives a range, keep the range.\n- timeline: keep the customer's wording, tidied. Example: \"3 weeks\", \"1 month\", \"By December\", \"ASAP\", \"Next quarter\".\n- urgency: must be exactly \"Low\", \"Medium\", \"High\" or null.\n  \"no rush\", \"not urgent\", \"whenever\" -> Low\n  \"fairly soon\", \"this month\", \"soonish\" -> Medium\n  \"ASAP\", \"very urgent\", \"urgently\", \"immediately\", \"I need it now\" -> High\n  Only set urgency if the customer expresses it. Do NOT derive urgency from the timeline alone.\n\nEXAMPLES\nExisting: all seven keys null\nMessage: \"Hi, I'm Amaka, 08012345678. I own a fashion brand and need an ecommerce website. My budget is ₦500k and I want it done in 3 weeks. It's very urgent.\"\nOutput: {\"customer_name\":\"Amaka\",\"phone_number\":\"08012345678\",\"business_type\":\"Fashion brand\",\"service_needed\":\"Ecommerce website\",\"budget\":\"₦500,000\",\"timeline\":\"3 weeks\",\"urgency\":\"High\"}\n\nExisting: {\"customer_name\":\"Amaka\",\"phone_number\":null,\"business_type\":null,\"service_needed\":null,\"budget\":null,\"timeline\":null,\"urgency\":null}\nThe workflow just asked for: phone_number\nMessage: \"0801 234 5678\"\nOutput: {\"customer_name\":\"Amaka\",\"phone_number\":\"08012345678\",\"business_type\":null,\"service_needed\":null,\"budget\":null,\"timeline\":null,\"urgency\":null}\n\nExisting: all seven keys null\nThe workflow just asked for: customer_name and phone_number\nMessage: \"Amaka 0801 234 5678\"\nOutput: {\"customer_name\":\"Amaka\",\"phone_number\":\"08012345678\",\"business_type\":null,\"service_needed\":null,\"budget\":null,\"timeline\":null,\"urgency\":null}\n\nExisting: all seven keys null\nMessage: \"Hi, I need a website for my business.\"\nOutput: {\"customer_name\":null,\"phone_number\":null,\"business_type\":null,\"service_needed\":\"Website\",\"budget\":null,\"timeline\":null,\"urgency\":null}\n\nReturn the JSON object now.";

const tg = $('Extract Telegram Data').first().json;

// Rows returned by "Find Session" (may be one row, or one empty item if none was found)
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r['Telegram User ID'] && String(r['Telegram User ID']).trim() === tg.telegram_user_id);
// If duplicates ever exist, use the most recent one.
const row = rows.length ? rows[rows.length - 1] : null;

// Did a customer whose lead is already completed just say thank you?
const msgLower = (tg.message_text || '').trim().toLowerCase();
const looksLikeThanks = msgLower.length <= 60 &&
  /\b(thanks|thank you|thank u|thankyou|thx|tnx|much appreciated|appreciate it)\b/.test(msgLower);
const thanksAfterComplete = !!(row && String(row['State']).trim() === 'completed' && looksLikeThanks);

const clean = (v) => (v === undefined || v === null || String(v).trim() === '') ? null : String(v).trim();

let session = {
  customer_name: null, phone_number: null, business_type: null,
  service_needed: null, budget: null, timeline: null, urgency: null
};
let state = 'new';
let originalMessage = '';

// "/start" always begins a fresh conversation. A "completed" session is also treated as finished.
const isRestart = (tg.message_text || '').trim().toLowerCase() === '/start';
if (row && !isRestart && String(row['State']).trim() !== 'completed') {
  session = {
    customer_name: clean(row['Customer Name']),
    phone_number: clean(row['Phone Number']),
    business_type: clean(row['Business Type']),
    service_needed: clean(row['Service Needed']),
    budget: clean(row['Budget']),
    timeline: clean(row['Timeline']),
    urgency: clean(row['Urgency'])
  };
  state = clean(row['State']) || 'new';
  originalMessage = clean(row['Original Message']) || '';
}

// Which field did the bot last ask about? (helps the AI read short answers)
const askedMap = {
  waiting_for_contact: 'customer_name and phone_number',
  waiting_for_name: 'customer_name',
  waiting_for_phone: 'phone_number',
  waiting_for_business_type: 'business_type',
  waiting_for_service: 'service_needed',
  waiting_for_budget: 'budget',
  waiting_for_timeline: 'timeline',
  waiting_for_urgency: 'urgency'
};
const askedField = askedMap[state] || null;

const userPrompt =
  'Existing session data:\n' + JSON.stringify(session, null, 2) + '\n\n' +
  (askedField
    ? 'The workflow just asked the customer for: ' + askedField + '\n\n'
    : 'This is the start of a conversation. No question has been asked yet.\n\n') +
  'Customer\'s newest message (between the markers):\n<<<START>>>\n' + tg.message_text + '\n<<<END>>>\n\n' +
  'Return the updated JSON object.';

return [{
  json: {
    session,
    state,
    original_message: originalMessage,
    session_exists: !!row,
    thanks_after_complete: thanksAfterComplete,
    system_prompt: SYSTEM_PROMPT,
    user_prompt: userPrompt
  }
}];

// Turn Gemini's reply into a clean, validated object.
let raw = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text;

const fail = (reason) => [{ json: { parse_ok: false, error_reason: reason, raw_response: raw ?? null } }];

if (typeof raw !== 'string' || !raw.trim()) return fail('Empty or blocked response from Gemini');

raw = raw.replace(/```json|```/gi, '').trim();

let data;
try { data = JSON.parse(raw); }
catch (e) { return fail('Invalid JSON: ' + e.message); }

if (typeof data !== 'object' || data === null || Array.isArray(data)) return fail('JSON is not an object');

const clean = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (!s) return null;
  if (['null', 'n/a', 'none', 'unknown', 'not provided', 'undefined'].includes(s.toLowerCase())) return null;
  return s;
};

// Urgency must be exactly Low / Medium / High, otherwise null.
let urgency = clean(data.urgency);
if (urgency) {
  const u = urgency.toLowerCase();
  urgency = u === 'low' ? 'Low' : u === 'medium' ? 'Medium' : u === 'high' ? 'High' : null;
}

// Phone: keep digits and a leading +, and require a plausible length (7-15 digits).
let phone = clean(data.phone_number);
if (phone) {
  const digits = phone.replace(/\D/g, '');
  phone = (digits.length >= 7 && digits.length <= 15)
    ? (phone.trim().startsWith('+') ? '+' : '') + digits
    : null;
}

// Name: keep it reasonably short.
let name = clean(data.customer_name);
if (name && name.length > 80) name = name.slice(0, 80);

return [{
  json: {
    parse_ok: true,
    extracted: {
      customer_name: name,
      phone_number: phone,
      business_type: clean(data.business_type),
      service_needed: clean(data.service_needed),
      budget: clean(data.budget),
      timeline: clean(data.timeline),
      urgency
    }
  }
}];

// Merge AI output with the saved session, find the first missing field, decide the next step.

// ---- Settings you can change ----
const ASK_TOGETHER = false; // false = ask name and phone as two separate questions; true = ask both in one message
// The order the bot asks questions in.
const order = ['customer_name', 'phone_number', 'business_type', 'service_needed', 'budget', 'timeline', 'urgency'];
// ---------------------------------

const tg = $('Extract Telegram Data').first().json;
const prep = $('Prepare Session And Prompt').first().json;
const ext = $input.first().json.extracted;

// New value wins if the AI found one; otherwise keep what we already had.
const merged = {};
for (const f of order) merged[f] = ext[f] ?? prep.session[f] ?? null;

const questions = {
  customer_name: 'What is your name? 😊',
  phone_number: 'What is your phone number? 📱',
  business_type: 'What type of business do you run? 🏢',
  service_needed: 'What service are you looking for? 🛠️',
  budget: 'What is your estimated budget for the project? 💰',
  timeline: 'When would you like the project completed? 📅',
  urgency: 'How urgent is this project? ⏰ You can choose Low, Medium, or High.'
};
const stateFor = {
  customer_name: 'waiting_for_name',
  phone_number: 'waiting_for_phone',
  business_type: 'waiting_for_business_type',
  service_needed: 'waiting_for_service',
  budget: 'waiting_for_budget',
  timeline: 'waiting_for_timeline',
  urgency: 'waiting_for_urgency'
};

const missing = order.filter(f => !merged[f]);
const hasUserId = !!tg.telegram_user_id;
const isComplete = missing.length === 0 && hasUserId;

let state, replyText;
let nextField = null; // which question comes next (used by the "Which Question?" switch)

if (isComplete) {
  state = 'completed';
  replyText = "Thanks! ✅ I've received your project details. Our team will review your request and get back to you soon. 🙌";
} else {
  nextField = missing[0] || null;

  // Work out which question we are about to ask.
  const bothContactMissing = missing.includes('customer_name') && missing.includes('phone_number');
  let question;
  if (bothContactMissing && ASK_TOGETHER) {
    state = 'waiting_for_contact';
    question = 'What is your name and phone number? 😊📱';
  } else {
    state = stateFor[nextField];
    question = questions[nextField];
  }

  // Use the customer's first name when we know it: "Thanks Amaka! ..."
  const firstName = merged.customer_name ? String(merged.customer_name).trim().split(/\s+/)[0] : '';
  const thanks = firstName ? 'Thanks ' + firstName + '! ' : 'Thanks! ';

  const isGreeting = /^\s*(hi|hello|hey|hola|good\s+(morning|afternoon|evening))\W*$/i.test(tg.message_text || '');

  let intro;
  if (prep.state === 'new' && !firstName) intro = 'Welcome to Lead Qualifier! 👋 ';      // very first message
  else if (prep.state === state && isGreeting) intro = 'Welcome back! 👋 ';               // customer returns mid-conversation
  else if (prep.state === state) intro = "Sorry, I didn't catch that. 😅 ";               // same question again
  else intro = thanks;                                                                  // normal follow-up

  replyText = intro + question;
}

// Keep the first real message (not a /start command) as the original message.
const firstReal = tg.message_text && !tg.message_text.startsWith('/') ? tg.message_text : '';

return [{
  json: {
    telegram_user_id: tg.telegram_user_id,
    telegram_username: tg.telegram_username,
    chat_id: tg.chat_id,
    ...merged,
    original_message: prep.original_message || firstReal,
    missing_fields: missing,
    next_field: nextField,
    is_complete: isComplete,
    state,
    reply_text: replyText,
    updated_at: new Date().toISOString()
  }
}];

// Look at existing Lead IDs (L-001, L-002 ...) and create the next one.
const merged = $('Merge And Check Fields').first().json;

let max = 0;
for (const item of $input.all()) {
  const id = String(item.json['Lead ID'] || '');
  const m = id.match(/^L-(\d+)$/);
  if (m) max = Math.max(max, parseInt(m[1], 10));
}

return [{
  json: {
    ...merged,
    lead_id: 'L-' + String(max + 1).padStart(3, '0'),
    created_at: new Date().toISOString()
  }
}];

// Handles BOTH typed messages and button presses (callback_query).
const upd = $input.first().json;
const cb = upd.callback_query;

if (cb) {
  const from = cb.from || {};
  const data = String(cb.data || '').trim();
  return [{
    json: {
      telegram_user_id: from.id !== undefined ? String(from.id) : '',
      telegram_username: from.username ? '@' + from.username : '',
      chat_id: (cb.message && cb.message.chat && cb.message.chat.id !== undefined) ? cb.message.chat.id : (from.id ?? null),
      message_text: data,
      callback_query_id: cb.id || '',
      is_button: true,
      has_text: data.length > 0 && from.id !== undefined
    }
  }];
}

const msg = upd.message || {};
const from = msg.from || {};
const text = typeof msg.text === 'string' ? msg.text.trim() : '';

return [{
  json: {
    telegram_user_id: from.id !== undefined ? String(from.id) : '',
    telegram_username: from.username ? '@' + from.username : '',
    chat_id: (msg.chat && msg.chat.id !== undefined) ? msg.chat.id : (from.id ?? null),
    message_text: text,
    callback_query_id: '',
    is_button: false,
    has_text: text.length > 0 && from.id !== undefined
  }
}];
